// Shared UI primitives, Material 3 (Material You). Import from `components/ui`.
// Tokens: src/m3.css (generated by scripts/m3_theme.mjs) -> tailwind.config.js. Legacy names (bg surface ink muted line low watch act info accent nodata,
// plus `-soft` / `-ink` variants) are aliases of the M3 roles. Icons: Material Symbols Rounded via <Icon>.
import { useEffect, useId, useRef, type ButtonHTMLAttributes, type KeyboardEvent, type ReactNode } from 'react'
import type { Band } from '../../types'
import { bandTone, bandWord, type Tone } from '../../lib/plain'
import { Icon, type IconName } from './Icon'
import { BTN_BASE, BTN_S, BTN_V, CARD, CHIP_BASE, CHIP_OFF, CHIP_ON, cx, type BtnVariant } from './m3'

export { Icon, type IconName }
export { AiBadge, AI_NAME, type AiBadgeProps, type AiFeature } from './AiBadge'
export { cx }

// ------------------------------------------------------------------ Pill / TrafficLight
const PILL: Record<Tone, string> = {
  low: 'bg-low-soft text-low-ink border-low/30',
  watch: 'bg-watch-soft text-watch-ink border-watch/30',
  act: 'bg-act-soft text-act-ink border-act/30',
  info: 'bg-info-soft text-info-ink border-info/30',
  accent: 'bg-accent-soft text-accent-ink border-accent/30',
  muted: 'bg-surface-container text-muted border-outline-variant',
  nodata: 'bg-surface-container text-muted border-outline-variant',
}
/** Filled lamp colours. Marks carry a thin dark ring so the amber lamp keeps its edge on light containers. */
const DOT: Record<Tone, string> = { low: 'bg-low-fill', watch: 'bg-watch-fill', act: 'bg-act-fill', info: 'bg-tertiary', accent: 'bg-primary', muted: 'bg-outline', nodata: 'bg-outline-variant' }
const RING = 'shadow-[inset_0_0_0_1px_rgb(0_0_0/0.28)]'

export interface PillProps { tone?: Tone; children: ReactNode; icon?: ReactNode; dot?: boolean; size?: 'sm' | 'md'; className?: string; title?: string }
/** Static M3 assist-style chip. `tone` picks the semantic container; `dot` adds a filled circle. */
export function Pill({ tone = 'muted', children, icon, dot, size = 'sm', className, title }: PillProps) {
  return (
    <span title={title} className={cx('inline-flex items-center gap-1.5 whitespace-nowrap rounded-m3-sm border', size === 'sm' ? 'h-6 px-2 md-label-medium' : 'h-8 px-3 md-label-large', PILL[tone], className)}>
      {dot && <i className={cx('inline-block h-2.5 w-2.5 rounded-full', DOT[tone], RING)} aria-hidden />}
      {icon}{children}
    </span>
  )
}

export type TrafficBand = Band | 'watch' | 'act' | 'nodata' | null | undefined
const toBand = (b: TrafficBand): Band | null => (b === 'act' ? 'high' : b === 'watch' ? 'medium' : b === 'nodata' ? 'no_data' : (b ?? null))

export interface TrafficLightProps {
  /** Risk band from the data (`low|medium|high|no_data`) or the semantic names (`low|watch|act|nodata`). */
  band: TrafficBand
  /** `pill` (assist chip: filled circle + word), `dot` (colour only, with aria-label), `badge` (large assist chip, for Level 0). */
  variant?: 'pill' | 'dot' | 'badge'
  size?: 'sm' | 'md'
  label?: string // override the word
  estimated?: boolean // adds a dotted ring: value is imputed
  className?: string
}
export function TrafficLight({ band, variant = 'pill', size = 'sm', label, estimated, className }: TrafficLightProps) {
  const b = toBand(band)
  const tone = bandTone(b)
  const word = label ?? bandWord(b)
  if (variant === 'dot') {
    return <i role="img" aria-label={word} title={word} className={cx('inline-block h-3.5 w-3.5 shrink-0 rounded-full', DOT[tone], RING, estimated && 'outline-dotted outline-2 outline-offset-2 outline-on-surface/60', className)} />
  }
  if (variant === 'badge') {
    return (
      <span className={cx('inline-flex h-10 items-center gap-2.5 rounded-m3-sm border px-4 md-title-medium', PILL[tone], className)}>
        <i className={cx('inline-block h-4 w-4 rounded-full', DOT[tone], RING, estimated && 'outline-dotted outline-2 outline-offset-2 outline-on-surface/60')} aria-hidden />
        {word}
      </span>
    )
  }
  return <Pill tone={tone} dot size={size} className={className}>{word}{estimated && <span className="font-normal opacity-80">· estimated</span>}</Pill>
}

/** Legacy name kept for existing imports. */
export function BandPill({ band, className = '' }: { band: Band | null | undefined; className?: string }) {
  return <TrafficLight band={band} className={className} />
}

/** "estimated" tag for imputed values; the tooltip explains where the estimate comes from. */
export function EstimatedTag({ from, className }: { from?: string; className?: string }) {
  return (
    <Tooltip content={from ? `Estimated from ${from}` : 'Estimated from nearby data, not measured here'}>
      <span tabIndex={0} className={cx('inline-flex items-center rounded-m3-xs border border-dotted border-on-surface/50 px-1.5 md-label-small text-muted', className)}>estimated</span>
    </Tooltip>
  )
}

// ------------------------------------------------------------------ Card / Stat
export interface CardProps { title?: ReactNode; right?: ReactNode; children?: ReactNode; className?: string; tone?: Tone | 'plain'; padded?: boolean }
export function Card({ title, right, children, className, tone = 'plain', padded = true }: CardProps) {
  const t = tone === 'plain' ? CARD : PILL[tone] + ' rounded-m3-md border'
  return (
    <section className={cx(t, padded && 'p-4', className)}>
      {(title || right) && (
        <div className="mb-3 flex items-center justify-between gap-2">
          <h3 className="md-title-medium text-on-surface">{title}</h3>
          {right}
        </div>
      )}
      {children}
    </section>
  )
}

export interface StatProps { dense?: boolean; label: ReactNode; value: ReactNode; unit?: string; sub?: ReactNode; icon?: ReactNode; tone?: Tone; estimated?: boolean; className?: string }
/** Big number with a plain label. Keep `value` rounded and put the unit in `unit` ("lakh tonnes", "children under 5"). */
export function Stat({ label, value, unit, sub, icon, tone, estimated, className, dense }: StatProps) {
  return (
    <div className={cx('min-w-0', CARD, dense ? 'px-4 py-3' : 'p-4', className)}>
      <div className="flex items-center gap-1.5 md-body-medium text-muted">{icon && <span aria-hidden className="flex text-primary">{icon}</span>}<span className="min-w-0">{label}</span>{estimated && <EstimatedTag />}</div>
      <div className="mt-1 flex flex-wrap items-baseline gap-x-1.5">
        <span className={cx('md-headline-medium tabular-nums', tone === 'act' ? 'text-act-ink' : tone === 'watch' ? 'text-watch-ink' : tone === 'low' ? 'text-low-ink' : 'text-on-surface')}>{value}</span>
        {unit && <span className="md-body-medium text-muted">{unit}</span>}
      </div>
      {sub && <div className="mt-0.5 md-body-small text-muted">{sub}</div>}
    </div>
  )
}

// ------------------------------------------------------------------ Button / IconButton / Chip / FAB
export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** primary = filled, secondary = tonal, outlined, ghost = text, danger = filled error. */
  variant?: BtnVariant
  size?: 'sm' | 'md' | 'lg' // sm is 40 px with a 48 px hit area; md 48; lg 56
  loading?: boolean
  iconLeft?: ReactNode
  block?: boolean
}
export function Button({ variant = 'secondary', size = 'md', loading, iconLeft, block, className, children, disabled, type = 'button', ...rest }: ButtonProps) {
  return (
    <button
      type={type} disabled={disabled || loading}
      className={cx(BTN_BASE, BTN_V[variant], BTN_S[size], block && 'w-full', className)}
      {...rest}
    >
      {loading ? <span className="h-[18px] w-[18px] animate-spin rounded-full border-2 border-current border-t-transparent" aria-hidden /> : iconLeft}
      {children}
    </button>
  )
}

/** Standard M3 icon button: 40 px visual, 48 px hit area. `label` is the accessible name. */
export function IconButton({ icon, label, onClick, className, fill, size = 24, ...rest }: { icon: IconName; label: string; fill?: boolean; size?: number } & Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label'>) {
  return (
    <button type="button" aria-label={label} title={label} onClick={onClick} className={cx('md-state md-hit inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-on-surface-variant', className)} {...rest}>
      <Icon name={icon} fill={fill} size={size} />
    </button>
  )
}

export interface ChipProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
  selected?: boolean
  children: ReactNode
  /** `md` 32 px (compact), `lg` 40 px (farmer: larger text, wrapping labels). */
  size?: 'md' | 'lg'
}
/** M3 filter chip: outlined, secondary-container + check icon when selected. Pass role="radio" + aria-checked, or aria-pressed. */
export function Chip({ selected, children, size = 'md', className, type = 'button', ...rest }: ChipProps) {
  return (
    <button type={type} className={cx(CHIP_BASE, selected ? CHIP_ON : CHIP_OFF, size === 'lg' ? 'min-h-10 px-4 py-1.5 text-left' : 'h-8 px-3', selected && 'pl-2', className)} {...rest}>
      {selected && <Icon name="check" size={18} />}
      {children}
    </button>
  )
}

/** Extended FAB (primary container). `collapsed` shows the icon only (label stays as the accessible name), as M3 does on small screens. */
export function Fab({ icon, label, onClick, className, collapsed }: { icon: IconName; label: string; onClick: () => void; className?: string; collapsed?: boolean }) {
  return (
    <button type="button" onClick={onClick} aria-label={collapsed ? label : undefined} title={collapsed ? label : undefined} className={cx('md-state inline-flex h-14 items-center justify-center gap-3 rounded-m3-lg bg-primary-container md-label-large text-on-primary-container shadow-elev-3 transition-shadow hover:shadow-elev-3', collapsed ? 'w-14' : 'pl-4 pr-5', className)}>
      <Icon name={icon} />{!collapsed && label}
    </button>
  )
}

// ------------------------------------------------------------------ Field (outlined select)
/** Outlined M3 select with a label notch on the border. `fieldBg` names the surface role behind it (so the notch blends in). */
export function SelectField({ label, value, onChange, children, className, dense, hideLabel, fieldBg, id }: {
  label: string; value: string; onChange: (v: string) => void; children: ReactNode; className?: string; dense?: boolean; hideLabel?: boolean; fieldBg?: string; id?: string
}) {
  return (
    <label className={cx('md-field', className)} style={fieldBg ? ({ '--md-field-bg': `rgb(var(--md-rgb-${fieldBg}))` } as React.CSSProperties) : undefined}>
      <span className={hideLabel ? 'sr-only' : 'md-field-label md-body-small'}>{label}</span>
      <select id={id} value={value} onChange={(e) => onChange(e.target.value)} className={cx('md-control md-body-large', dense && 'md-control-dense md-body-medium')}>{children}</select>
      <Icon name="expand_more" size={20} className="md-field-chevron" />
    </label>
  )
}

// ------------------------------------------------------------------ Tabs
export interface TabItem<T extends string = string> { id: T; label: ReactNode; icon?: IconName; badge?: ReactNode; title?: string }
export interface TabsProps<T extends string = string> {
  tabs: TabItem<T>[]
  value: T
  onChange: (id: T) => void
  /** `underline` (M3 primary tabs), `segmented` (outlined segmented button), `bottom` (M3 navigation bar, 80 px). */
  variant?: 'underline' | 'segmented' | 'bottom'
  ariaLabel?: string
  className?: string
}
/** Accessible tab list (arrow keys, roles). Pair with <TabPanel>. */
export function Tabs<T extends string>({ tabs, value, onChange, variant = 'underline', ariaLabel, className }: TabsProps<T>) {
  const uid = useId()
  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const i = tabs.findIndex((t) => t.id === value)
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
      const n = tabs[(i + (e.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length]
      onChange(n.id)
      e.preventDefault()
      requestAnimationFrame(() => document.getElementById(`${uid}-${n.id}`)?.focus())
    }
  }
  const wrap = variant === 'segmented' ? 'inline-flex h-10 rounded-full border border-outline' : variant === 'bottom' ? 'grid auto-cols-fr grid-flow-col bg-surface-container pb-safe' : 'flex overflow-x-auto border-b border-outline-variant hide-scrollbar'
  return (
    <div role="tablist" aria-label={ariaLabel} onKeyDown={onKey} className={cx(wrap, className)}>
      {tabs.map((t, idx) => {
        const on = t.id === value
        const base = 'md-state relative inline-flex shrink-0 items-center justify-center whitespace-nowrap transition-colors md-focus-inset'
        const v =
          variant === 'segmented' ? cx('md-hit h-10 gap-2 px-4 md-label-large', idx === 0 ? 'rounded-l-full' : 'border-l border-outline', idx === tabs.length - 1 && 'rounded-r-full', on ? 'bg-secondary-container text-on-secondary-container' : 'text-on-surface')
          : variant === 'bottom' ? cx('h-20 flex-col gap-1 px-2 pb-4 pt-3 md-label-medium', on ? 'text-on-surface' : 'text-on-surface-variant')
          : cx('min-h-[48px] gap-2 px-4 md-label-large', on ? 'text-primary' : 'text-on-surface-variant')
        return (
          <button
            key={t.id} id={`${uid}-${t.id}`} role="tab" type="button" aria-selected={on} tabIndex={on ? 0 : -1} title={t.title}
            onClick={() => onChange(t.id)} className={cx(base, v)}
          >
            {variant === 'segmented' && on && <Icon name="check" size={18} />}
            {variant === 'bottom' ? (
              <span className={cx('flex h-8 w-16 items-center justify-center rounded-full transition-colors', on ? 'bg-secondary-container text-on-secondary-container' : '')}>{t.icon && <Icon name={t.icon} fill={on} />}</span>
            ) : variant === 'underline' && t.icon ? <Icon name={t.icon} size={20} /> : null}
            <span>{t.label}</span>
            {t.badge != null && <span className="inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-error px-1 md-label-small text-on-error">{t.badge}</span>}
            {variant === 'underline' && on && <i className="absolute inset-x-3 bottom-0 h-[3px] rounded-t-full bg-primary" aria-hidden />}
          </button>
        )
      })}
    </div>
  )
}
export function TabPanel({ id, value, children, className }: { id: string; value: string; children: ReactNode; className?: string }) {
  if (id !== value) return null
  return <div role="tabpanel" className={className}>{children}</div>
}

/** Legacy segmented control (same look as Tabs variant=segmented; `size` kept for existing callers). M3 outlined segmented button. */
export function Segmented<T extends string>({
  value, options, onChange, size = 'md',
}: { value: T; options: { id: T; label: ReactNode; title?: string }[]; onChange: (v: T) => void; size?: 'sm' | 'md' }) {
  return (
    <div className={cx('inline-flex rounded-full border border-outline', size === 'sm' ? 'h-8' : 'h-10')} role="tablist">
      {options.map((o, i) => {
        const on = o.id === value
        return (
          <button
            key={o.id} type="button" title={o.title} role="tab" aria-selected={on} onClick={() => onChange(o.id)}
            className={cx('md-state md-focus-inset relative inline-flex items-center justify-center gap-1.5 whitespace-nowrap', size === 'sm' ? 'md-hit-lg px-3 md-label-medium' : 'md-hit px-4 md-label-large', i === 0 ? 'rounded-l-full' : 'border-l border-outline', i === options.length - 1 && 'rounded-r-full', on ? 'bg-secondary-container text-on-secondary-container' : 'text-on-surface')}
          >
            {on && <Icon name="check" size={size === 'sm' ? 16 : 18} />}
            {o.label}
          </button>
        )
      })}
    </div>
  )
}

// ------------------------------------------------------------------ Tooltip
export interface TooltipProps { content: ReactNode; children: ReactNode; side?: 'top' | 'bottom'; className?: string }
/** M3 plain tooltip: CSS-only hover/focus. Wrap a focusable element (or give the child tabIndex=0) for keyboard and touch use. */
export function Tooltip({ content, children, side = 'top', className }: TooltipProps) {
  return (
    <span className={cx('group relative inline-flex', className)}>
      {children}
      <span
        role="tooltip"
        className={cx('pointer-events-none absolute left-1/2 z-50 w-max max-w-[16rem] -translate-x-1/2 rounded-m3-xs bg-inverse-surface px-2 py-1 md-body-small text-inverse-on-surface opacity-0 transition-opacity group-focus-within:opacity-100 group-hover:opacity-100', side === 'top' ? 'bottom-full mb-1.5' : 'top-full mt-1.5')}
      >
        {content}
      </span>
    </span>
  )
}

// ------------------------------------------------------------------ Skeleton / Progress / ErrorNote
export function Skeleton({ className = '' }: { className?: string }) {
  return <div className={`skeleton ${className}`} aria-hidden />
}
/** M3 linear progress, indeterminate. */
export function LinearProgress({ label, className }: { label?: string; className?: string }) {
  return <div role="progressbar" aria-label={label ?? 'Loading'} className={cx('md-progress', className)} />
}
export function Spinner({ label }: { label?: string }) {
  return (
    <div className="flex w-56 flex-col items-center gap-3 md-body-medium text-muted" role="status">
      <LinearProgress label={label} />
      {label}
    </div>
  )
}
export function ErrorNote({ children, onRetry }: { children: ReactNode; onRetry?: () => void }) {
  return (
    <div role="alert" className="flex items-start gap-3 rounded-m3-md bg-error-container p-3 md-body-medium text-on-error-container">
      <Icon name="warning" size={20} className="mt-0.5" fill />
      <div className="min-w-0 flex-1">
        {children}
        {onRetry && <button onClick={onRetry} className="md-state relative ml-2 rounded-full px-2 font-medium underline md-hit">Try again</button>}
      </div>
    </div>
  )
}

// ------------------------------------------------------------------ Sheet / Modal
export interface SheetProps {
  open: boolean
  onClose: () => void
  title?: ReactNode
  /** `right` side sheet, `bottom` modal bottom sheet, `center` basic dialog. */
  side?: 'right' | 'bottom' | 'center'
  children: ReactNode
  /** Tailwind width/max-width classes for right/center, e.g. `max-w-2xl`. */
  widthClass?: string
  /** false = cannot be dismissed (first-load role picker). */
  dismissible?: boolean
  ariaLabel?: string
  footer?: ReactNode
}
export function Sheet({ open, onClose, title, side = 'right', children, widthClass, dismissible = true, ariaLabel, footer }: SheetProps) {
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!open) return
    const prev = document.activeElement as HTMLElement | null
    ref.current?.focus()
    const h = (e: globalThis.KeyboardEvent) => { if (e.key === 'Escape' && dismissible) onClose() }
    window.addEventListener('keydown', h)
    return () => { window.removeEventListener('keydown', h); prev?.focus?.() }
  }, [open, dismissible, onClose])
  if (!open) return null
  const pos = side === 'center' ? 'items-center justify-center p-4' : side === 'bottom' ? 'items-end justify-center' : 'items-stretch justify-end'
  const panel =
    side === 'center' ? cx('max-h-[90dvh] w-full rounded-m3-xl bg-surface-container-high shadow-elev-3', widthClass ?? 'max-w-lg')
    : side === 'bottom' ? 'max-h-[88dvh] w-full rounded-t-m3-xl bg-surface-container-low pb-safe shadow-elev-3'
    : cx('h-full w-full rounded-l-m3-lg bg-surface-container-low shadow-elev-3', widthClass ?? 'max-w-md')
  const dialog = side === 'center'
  return (
    <div className={cx('fixed inset-0 z-50 flex bg-scrim/[0.32]', pos)} onMouseDown={(e) => { if (e.target === e.currentTarget && dismissible) onClose() }}>
      <div ref={ref} tabIndex={-1} role="dialog" aria-modal="true" aria-label={ariaLabel ?? (typeof title === 'string' ? title : undefined)} className={cx('flex flex-col overflow-hidden outline-none', panel)}>
        {side === 'bottom' && <div className="mx-auto mt-3 h-1 w-8 shrink-0 rounded-full bg-on-surface-variant/40" aria-hidden />}
        {(title || dismissible) && (
          <div className={cx('flex shrink-0 items-start justify-between gap-3', dialog ? 'px-6 pb-2 pt-6' : 'px-4 py-3')}>
            <h2 className={cx('text-on-surface', dialog ? 'md-headline-small' : 'md-title-large')}>{title}</h2>
            {dismissible && <IconButton icon="close" label="Close" onClick={onClose} className="-mr-1" />}
          </div>
        )}
        <div className="min-h-0 flex-1 overflow-y-auto">{children}</div>
        {footer && <div className="shrink-0 border-t border-outline-variant px-4 py-3">{footer}</div>}
      </div>
    </div>
  )
}
export const Modal = (p: Omit<SheetProps, 'side'>) => <Sheet {...p} side="center" />
